import json

def next_action(result):
    # Parse the result from run_command if it exists
    try:
        result_data = json.loads(result)
    except (TypeError, json.JSONDecodeError):
        result_data = result

    # Check if the result indicates a process completion
    if "exit_code" in result_data:
        if result_data["exit_code"] == 0:
            return {"tool": "final_report", "success": True}
        else:
            return {"tool": "final_report", "success": False}
    # Check if the result indicates a running process
    elif "status" in result_data and result_data["status"] == "running":
        return {"tool": "get_process_status", "process_id": result_data["process_id"]}
    # Handle unknown status or incomplete result
    else:
        raise ValueError("Unknown status or incomplete result")
